// TH18 v1.00a Stage 5 mid-stage MainSub04.
// Source: st05.ecl.txt:1117-1128 (wave), :72-94 (Cir01 body move), :96-126 (Cir01 firing).
// Source local wave t0 = card frame 124: shell 120-frame pre-roll, then one Cir01 / 20 frames.
const TIME_LIMIT: int = 2900;
const TH18_INVERT_RICE: int = 592; // source etSprite(0,15,13): type 15 InvertRice, color 13.

// st05.ecl.txt:72-94 + :96-126. One task keeps both the body move and the
// firing task; the source async fired from the post-movement FINAL position.
async sub cir01() {
    set_invuln(65535);
    set_hurtbox(14fx); // source setHurtbox(28,28): source hit radius 28*0.5
    set_hitbox(8fx);   // source setHitbox(16,16): source body radius 16*0.5

    // st05.ecl.txt:108 + :116-121: count 10/60/70/80, interval 32/8/6/4.
    var rank: int = global(GVAR_RANK);
    var count: int = 10;
    var gap: int = 32;
    if rank == 1 { count = 60; gap = 8; }
    else if rank == 2 { count = 70; gap = 6; }
    else if rank == 3 { count = 80; gap = 4; }

    // st05.ecl.txt:80 moveVel(112.5deg + RANDF2*10deg, 2.0); RANDF2 is [-1,1].
    var base_a: int = 20480 + ((rand(65536) - 32768) * 1820) / 32768;
    var beta: int = base_a; // st05.ecl.txt:81 axis snapshot = ABS_ANGLE at setup
    var sb: fx = sin(beta as angle);
    var cb: fx = cos(beta as angle);
    // st05.ecl.txt:81 moveEllipseRel(0, 2deg, 10, 0, ABS_ANGLE, 0), s=0:
    // REL = 10*sin(theta-beta) * (-sin beta, cos beta); theta = 2deg*tick.
    var phase: int = 0;
    var negbeta: int = 0 - beta;
    if negbeta < 0 { negbeta = negbeta + 65536; }
    var prev: fx = sin(negbeta as angle); // sin(0-beta)
    var r0x: fx = 10fx * sb * sb;         // REL at theta=0
    var r0y: fx = 0fx - 10fx * sb * cb;
    move_to(0, $self_x + r0x, $self_y + r0y, EASE_LINEAR); // setter's same-frame position

    var olda: int = base_a;
    var olds: fx = 2fx;
    var d1: int = 0;
    var cur1: int = base_a;
    var d2: int = 0;
    var cur2: int = base_a;
    var t: int = 0;
    var shots: int = count;
    var next_shot: int = 61; // source async first tick f+2, wait(60) -> f+62
    wait(1); // task first tick is f+1; loop tick t=1 is f+2

    loop {
        t = t + 1;
        var a: int = olda;
        var s: fx = olds;
        // st05.ecl.txt:83-86: wait 120, moveVelTime(120,0,ANGLE_PLAYER,1),
        // wait 120, moveVelTime(120,0,-90deg+RANDF2*20deg,2); mode0 = linear.
        if t > 120 && t <= 240 {
            var k1: int = t - 120;
            a = olda + d1 * k1 / 120;
            s = 2fx - (k1 as fx) / 120fx;
        } else if t > 240 && t <= 360 {
            var k2: int = t - 240;
            a = cur1 + d2 * k2 / 120;
            s = 1fx + (k2 as fx) / 120fx;
        } else if t > 360 {
            a = cur2;
            s = 2fx;
        }

        // Movement tick: ellipse phase advances first, then both layers move.
        phase = phase + 364; // 2deg/tick
        if phase >= 65536 { phase = phase - 65536; }
        var da: int = phase - beta;
        if da < 0 { da = da + 65536; }
        var sn: fx = sin(da as angle);
        var dv: fx = 10fx * (sn - prev);
        prev = sn;
        var vx: fx = s * cos(a as angle) - dv * sb;
        var vy: fx = s * sin(a as angle) + dv * cb;
        move_vel_xy(0, vx, vy, EASE_LINEAR);

        // st05.ecl.txt:83-84: ANGLE_PLAYER read after the f+121 movement tick.
        if t == 120 {
            var aim: int = atan2($player_y - ($self_y + vy),
                                 $player_x - ($self_x + vx)) as int;
            d1 = aim - olda;
            if d1 > 32768 { d1 = d1 - 65536; }
            if d1 < -32768 { d1 = d1 + 65536; }
            cur1 = olda + d1;
        }
        // st05.ecl.txt:86: -90deg + RANDF2*20deg, sampled after the f+241 tick.
        if t == 240 {
            var t2: int = -16384 + ((rand(65536) - 32768) * 3641) / 32768;
            d2 = t2 - cur1;
            if d2 > 32768 { d2 = d2 - 65536; }
            if d2 < -32768 { d2 = d2 + 65536; }
            cur2 = t2;
        }

        // st05.ecl.txt:110-113 + :122: etAngle(RANDRAD,0) then etOn(0).
        if shots > 0 && t == next_shot {
            var ba: angle = rand(65536) as angle;
            // Fire from the post-movement FINAL position. The sole EX is ANIM a=1,
            // which retreats 4*velocity = 4*0.9 = 3.6px opposite the shot direction.
            var bx: fx = $self_x + vx - 3.6fx * cos(ba);
            var by: fx = $self_y + vy - 3.6fx * sin(ba);
            _ = fire(TH18_INVERT_RICE, 13, bx, by, 0.9fx, ba, none, none);
            shots = shots - 1;
            next_shot = next_shot + gap;
        }
        wait(1);
    }
}

// st05.ecl.txt:1117-1128 MainSub04: 110 scheduled Cir01, one every 20 frames.
// The source enmCreateF skips while boss0 exists; training fixes boss ended and
// keeps the complete 110-instance reward formation (split.md w05 note).
async sub wave() {
    wait(120); // shell pre-roll before source t0
    for i in 0..110 {
        // st05.ecl.txt:1123 enmCreateF("Cir01", RANDF2*128+128, -64, ...).
        // RANDF2 [-1,1] -> x in [0,256].
        var u: fx = (rand(65536) as fx) / 16384fx; // rand/16384 = 4*RANDF
        var x: fx = 128fx + (u - 2fx) * 64fx;
        _ = spawn_enemy(x, -64fx, 400, 0, 0, 0, cir01);
        wait(20);
    }
}

// Extra control enemy: (0,0), no body collision, invulnerable; only owns the
// phase timer/end event. Real Cir01 keep source-equivalent hit/hurt radii.
async sub boss_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_hitbox(0fx);
    set_hurtbox(0fx);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 100000, 0, 0, 0, boss_main);
    loop { wait(600); }
}
